Certainly! Below is a PowerShell script that performs the following:

- Enumerates vulnerable RDP configurations (e.g., checks if Network Level Authentication (NLA) is disabled, which is a common risky config).
- Tests CredSSP registry settings to verify if patches related to the CredSSP vulnerability (MS14-068) have been applied.
- Demonstrates a simulated check for the BlueKeep (CVE-2019-0708) vulnerability by verifying RDP version and certain registry keys, and attempts a crafted payload simulation (note: actual exploitation is dangerous and not included; this is a demonstration only).

---

### Notes before running:

- Run as Administrator.
- This script **does not exploit any vulnerability**, only performs checks and simulates payload verification.
- Some checks require remote registry or WMI access.
- BlueKeep vulnerability verification is based on known indicators and registry settings.
- Always test in safe environments.

---

```powershell
<#
.SYNOPSIS
    Patch and vulnerability validation script for RDP configurations, CredSSP registry settings, and BlueKeep vulnerability simulation.

.DESCRIPTION
    This script checks:
    - Vulnerable RDP configurations (NLA disabled, RDP version)
    - CredSSP patch registry settings for MS14-068
    - BlueKeep vulnerability indicators and simulates crafted payload test (safe check only)

.NOTES
    Run with Administrative privileges.
#>

function Get-RDPConfiguration {
    Write-Host "Checking RDP configuration..."

    # Check if RDP is enabled
    $rdpStatus = (Get-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server" -Name "fDenyTSConnections").fDenyTSConnections
    $rdpEnabled = if ($rdpStatus -eq 0) { $true } else { $false }
    Write-Host "RDP Enabled: $rdpEnabled"

    # Check if Network Level Authentication (NLA) is required
    $nlaStatus = (Get-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server\WinStations\RDP-Tcp" -Name "UserAuthentication").UserAuthentication
    $nlaRequired = if ($nlaStatus -eq 1) { $true } else { $false }
    Write-Host "Network Level Authentication (NLA) Required: $nlaRequired"

    # If RDP enabled but NLA disabled, this is a risky configuration
    if ($rdpEnabled -and -not $nlaRequired) {
        Write-Warning "RDP is enabled but NLA is NOT required. This configuration is vulnerable to unauthorized access."
    }
    else {
        Write-Host "RDP configuration appears secure regarding NLA."
    }
}

function Test-CredSSPRegistry {
    Write-Host "`nChecking CredSSP patch registry settings for MS14-068..."

    # CredSSP patch adds registry keys to mitigate vulnerability

    # Path to CredSSP policy keys
    $credsspPath = "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System\CredSSP\Parameters"

    if (Test-Path $credsspPath) {
        $policy = Get-ItemProperty -Path $credsspPath

        # Check AllowEncryptionOracle key (introduced for the vulnerability fix)
        if ($policy.PSObject.Properties.Name -contains "AllowEncryptionOracle") {
            $value = $policy.AllowEncryptionOracle
            switch ($value) {
                0 { Write-Host "CredSSP patch applied: Encryption Oracle Remediation set to 'Force Updated Clients' (0) - Secure" }
                1 { Write-Warning "CredSSP Encryption Oracle Remediation set to 'Mitigated' (1) - Partial mitigation" }
                2 { Write-Warning "CredSSP Encryption Oracle Remediation set to 'Vulnerable' (2) - Vulnerable" }
                default { Write-Warning "CredSSP Encryption Oracle Remediation set to unknown value: $value" }
            }
        }
        else {
            Write-Warning "AllowEncryptionOracle registry key not found. System might be vulnerable or unpatched."
        }
    }
    else {
        Write-Warning "CredSSP registry path not found. System might be unpatched or older."
    }
}

function Test-BlueKeepVulnerability {
    Write-Host "`nChecking for BlueKeep (CVE-2019-0708) vulnerability indicators..."

    # BlueKeep affects RDP on Windows 7, Server 2008 R2, Server 2008, XP, and Vista
    # Key indicators:
    # - RDP version < 6.1.7601.17514 (patched version)
    # - Specific registry keys indicating patch installed

    # Get RDP tcp driver version
    $rdpTcpDriver = Get-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server\WinStations\RDP-Tcp"
    $rdpVersion = (Get-Command "mstsc.exe").FileVersionInfo.FileVersion

    Write-Host "mstsc.exe (RDP client) version: $rdpVersion"

    # Check if system is Windows 7 or Server 2008 R2 or similar
    $osInfo = Get-CimInstance Win32_OperatingSystem
    Write-Host "Operating System: $($osInfo.Caption) Build: $($osInfo.BuildNumber)"

    # Check if required patches installed (KB4499175 or later for Windows 7/Server 2008 R2)
    # We can check installed hotfixes for BlueKeep patch
    $hotfixes = Get-HotFix | Where-Object { $_.HotFixID -in @("KB4499175", "KB4503276", "KB4512506") }

    if ($hotfixes) {
        Write-Host "BlueKeep patch hotfixes found:"
        $hotfixes | ForEach-Object { Write-Host " - $($_.HotFixID) installed on $($_.InstalledOn)" }
        Write-Host "System appears patched against BlueKeep."
        return
    }
    else {
        Write-Warning "No BlueKeep patch hotfixes found. System might be vulnerable."
    }

    # Additional registry check for Vulnerable RDP settings (simulate)
    $vulnerable = $false
    try {
        # Check RDP security layer: 0 = RDP Security Layer (less secure), 1 = Negotiate, 2 = SSL (more secure)
        $securityLayer = (Get-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\Terminal Server\WinStations\RDP-Tcp" -Name "SecurityLayer").SecurityLayer
        if ($securityLayer -eq 0) {
            Write-Warning "RDP Security Layer is set to RDP Security Layer (0) - vulnerable configuration."
            $vulnerable = $true
        }
        else {
            Write-Host "RDP Security Layer is set to $securityLayer (higher security)."
        }
    }
    catch {
        Write-Warning "Could not read RDP SecurityLayer registry key."
    }

    # Simulation of crafted payload test (NO actual exploit, safe simulation)
    Write-Host "`nSimulating BlueKeep crafted payload verification..."

    # Craft a dummy payload (purely demonstrative)
    $payload = [byte[]](0x03,0x00,0x00,0x13,0x0e,0xd0,0x00,0x00,0x12,0x34,0x00,0x02,0x08,0x00,0x03,0x00,0x00,0x00,0x00,0x00)

    # Normally, this payload would be sent to RDP port 3389 and response analyzed.
    # Here, we only simulate the step by checking port status.

    $rdpPortOpen = Test-NetConnection -ComputerName localhost -Port 3389 -WarningAction SilentlyContinue
    if ($rdpPortOpen.TcpTestSucceeded) {
        Write-Host "Port 3389 is open. (RDP service running)"
        Write-Host "Simulated payload would be sent here in a real test."
        if ($vulnerable) {
            Write-Warning "System is likely vulnerable to BlueKeep based on configuration and missing patches."
        }
        else {
            Write-Host "System configuration appears to mitigate BlueKeep risk."
        }
    }
    else {
        Write-Warning "Port 3389 is closed. RDP service not reachable."
    }
}

# Main
Write-Host "Starting patch validation and vulnerability checks..." -ForegroundColor Cyan
Get-RDPConfiguration
Test-CredSSPRegistry
Test-BlueKeepVulnerability
Write-Host "`nValidation complete." -ForegroundColor Green
```

