```python
import nmap
from rdpy.core import RDP
from rdpy.core.exceptions import ConnectionError

def scan_for_rdp_vulnerability(host, port):
    try:
        rdp = RDP()
        rdp.connect(host, port)
        # Check for BlueKeep vulnerability here
        if rdp.is_vulnerable_to_bluekeep():
            print(f"{host}:{port} is vulnerable to BlueKeep")
        else:
            print(f"{host}:{port} is not vulnerable to BlueKeep")
    except ConnectionError:
        print(f"Unable to connect to {host}:{port}")

def main():
    # Scan for hosts with open RDP ports
    nm = nmap.PortScanner()
    nm.scan(hosts='192.168.1.0/24', arguments='-p 3389 --open')

    for host in nm.all_hosts():
        for port in nm[host]['tcp'].keys():
            scan_for_rdp_vulnerability(host, port)

if __name__ == "__main__":
    main()
```

